/* Minimal photographic home screen. Other gameplay screens retain their own styling. */
#screen-menu.menu-screen {
  min-height:calc(100dvh - 3px);
  min-height:calc(100svh - 3px);
  position:relative;
  isolation:isolate;
  justify-content:flex-start;
  overflow:hidden;
  background-color:#090a0b;
  background-image:
    linear-gradient(180deg,rgba(3,4,6,.57) 0%,rgba(4,6,9,.33) 34%,rgba(5,7,9,.27) 62%,rgba(5,6,7,.40) 100%),
    url("./assets/showroom-home-bg.webp");
  background-position:center center;
  background-size:cover;
  background-repeat:no-repeat;
}
#screen-menu .menu-top {
  height:54px;
  min-height:54px;
  display:flex;
  justify-content:flex-end;
  align-items:center;
  border:none;
  padding:10px clamp(20px,3vw,48px);
  background:none;
}
#screen-menu .menu-status {
  color:#e4d5b5;
  font:700 10px/1 var(--mono);
  letter-spacing:.08em;
  padding:8px 11px;
  border:1px solid #af916858;
  border-radius:99px;
  background:#080b0f91;
}
#screen-menu .menu-layout {
  flex:1;
  min-height:0;
  display:flex;
  width:min(100%,1100px);
  margin:0 auto;
  justify-content:center;
  align-items:center;
  padding:0 20px 55px;
  gap:0;
}
#screen-menu .menu-lead {
  display:flex;
  flex-direction:column;
  align-items:center;
  text-align:center;
  width:100%;
  min-width:0;
  transform:translateY(-2%);
}
#screen-menu .brand-lockup-large {
  margin:0 0 clamp(22px,3vh,34px);
  align-items:center;
  text-align:center;
}
#screen-menu .brand-lockup-large .parent-wordmark {
  width:clamp(170px,19vw,258px);
  max-width:100%;
  height:auto;
  /* Exact existing image asset, no extra effects on the wordmark. */
}
/* True vector artwork: no background-clip:text, no inline glyph clipping, no plaque. */
#screen-menu .trade-wordmark-hero {
  display:block;
  width:min(700px,100%);
  max-width:100%;
  height:auto;
  margin:-19px 0 0;
  padding:0;
  overflow:visible;
  border:0;
  background:transparent;
  border-radius:0;
  box-shadow:none;
  filter:none;
  line-height:0;
}
#screen-menu .trade-wordmark-hero img {
  display:block;
  width:100%;
  height:auto;
  max-width:100%;
  object-fit:contain;
  overflow:visible;
}
#screen-menu .menu-actions {
  display:flex;
  width:min(425px,100%);
  margin:0;
  flex-direction:column;
  gap:12px;
}
#screen-menu .action-btn {
  min-height:68px;
  width:100%;
  display:flex;
  align-items:center;
  gap:17px;
  padding:10px 20px;
  border-radius:9px;
  text-align:left;
  background:linear-gradient(120deg,#030509df,#0b1015db);
  border:1px solid #b88d4d;
  color:#f4f1eb;
  box-shadow:0 5px 18px #0007;
  backdrop-filter:blur(5px);
  -webkit-backdrop-filter:blur(5px);
  transition:transform .15s,border-color .15s,background .15s;
}
#screen-menu .action-btn:hover {
  transform:translateY(-2px);
  border-color:#f7d99e;
  background:#1a1b1fe8;
}
#screen-menu .action-btn-primary {
  background:linear-gradient(165deg,#f7dba1 0%,#ddb067 48%,#b98438 100%);
  border:1px solid #eec37c;
  color:#111317;
}
#screen-menu .action-btn-primary:hover {
  background:linear-gradient(165deg,#ffebba,#eac381 55%,#cb9850);
  border-color:#fbe9c5;
}
#screen-menu .action-btn-secondary {
  background:#080b10e8;
  border-color:#b88d4d;
  color:#f4f1eb;
}
#screen-menu .button-mark {font:800 27px/1 var(--title);width:29px;flex:0 0 29px}
#screen-menu .action-btn strong {font:800 25px/1 var(--title);letter-spacing:.045em}
#screen-menu .action-btn small {font:500 10px/1.3 var(--body);margin-top:3px;color:inherit;opacity:.8}
#screen-menu .action-btn .arrow {font:500 33px/1 var(--title);margin-left:auto}
#screen-menu .menu-guide {
  width:min(425px,100%);
  max-width:none;
  margin:12px 0 0;
  padding:15px 17px;
  text-align:left;
  color:#e4e5e1;
  border:1px solid #927d5e;
  background:#080b0fe8;
  border-radius:8px;
  font-size:12px;
  line-height:1.6;
}
@media(max-width:780px) {
  #screen-menu .menu-layout {padding:0 16px 38px}
  #screen-menu .menu-lead {transform:none}
  #screen-menu .brand-lockup-large {margin-bottom:30px}
}
@media(max-width:570px) {
  #screen-menu.menu-screen {min-height:calc(100svh - 3px);background-position:49% center}
  #screen-menu .menu-top {height:44px;min-height:44px;padding:8px 12px}
  #screen-menu .menu-status {font-size:8px}
  #screen-menu .menu-layout {padding:10px 15px 30px}
  #screen-menu .brand-lockup-large .parent-wordmark {width:clamp(160px,45vw,218px)}
  #screen-menu .trade-wordmark-hero {width:min(700px,100%);margin-top:-12px}
  #screen-menu .brand-lockup-large {margin-bottom:25px}
  #screen-menu .menu-actions {gap:10px}
  #screen-menu .action-btn {min-height:63px;padding:10px 14px}
  #screen-menu .action-btn strong {font-size:22px}
  #screen-menu .button-mark {font-size:23px}
}
@media(max-height:690px) and (min-width:781px) {
  #screen-menu .brand-lockup-large {margin-bottom:22px}
  #screen-menu .action-btn {min-height:57px}
}

/* Optional, functional menu display settings. */
#screen-menu.menu-no-showroom {background-image:linear-gradient(145deg,#1e2226,#08090b 65%,#292213)}
#screen-menu.menu-no-motion *,
#screen-menu.menu-no-motion *::before,
#screen-menu.menu-no-motion *::after {animation:none!important;transition:none!important}
#screen-menu .menu-visually-hidden {position:absolute;width:1px;height:1px;padding:0;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}
#screen-menu .menu-setting-row {display:flex;align-items:center;justify-content:space-between;gap:12px;padding:8px 0;font:700 11px/1.2 var(--mono);color:#ebe0cb}
#screen-menu .menu-setting-row + .menu-setting-row {border-top:1px solid #5d5544}
#screen-menu .menu-setting-row button {min-width:60px;padding:6px 10px;border-radius:4px;background:#d4b076;color:#11161a;border:1px solid #e9c88f;font:800 11px/1 var(--mono)}


/* Multi-source trading game: management screens only. */
.trade-alert{margin:0 0 17px;border-left:3px solid #c9a56b;background:#182a32;padding:12px 15px;font-size:11px;line-height:1.6;color:#c4d2d4}
.trade-section{padding:0;margin:0 0 18px;overflow:hidden}
.trade-card-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;padding:16px}
.trade-card{background:linear-gradient(160deg,#1c3542,#132730);border:1px solid #385462;border-radius:8px;min-width:0;overflow:hidden}
.trade-card:hover{border-color:#738a8b}
.trade-card-top{padding:13px 14px 10px;display:flex;justify-content:space-between;align-items:flex-start;gap:10px}
.trade-card h3{font:800 clamp(20px,2.3vw,27px)/1 var(--title);letter-spacing:.025em;overflow-wrap:anywhere}
.trade-card-kicker{font:700 9px/1.4 var(--mono);color:#d9b97d;letter-spacing:.045em;display:block;margin-bottom:5px}
.trade-source{font:700 9px/1.2 var(--mono);padding:5px 7px;border:1px solid #668079;color:#e6d7ae;border-radius:4px;white-space:nowrap}
.trade-card-details{display:flex;flex-wrap:wrap;gap:6px;padding:0 14px 11px}
.trade-card-details span{font:600 10px/1.3 var(--body);color:#bcd0d3;border:1px solid #344b56;padding:4px 6px;border-radius:3px}
.trade-card-note{font-size:11px;line-height:1.55;color:#b4c6cc;margin:0 14px 13px;min-height:32px}
.trade-pricing{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:1px;background:#324a55;border-top:1px solid #324a55;border-bottom:1px solid #324a55}
.trade-pricing>div{padding:10px 13px;background:#142834;display:flex;flex-direction:column;gap:3px}
.trade-pricing small{font:700 9px/1.3 var(--mono);color:#98b5bd}
.trade-pricing strong{font:800 22px/1 var(--title);color:#fff3dc}
.trade-actions{padding:12px 14px 14px;display:flex;flex-direction:column;gap:9px}
.trade-action-row{display:flex;gap:8px;align-items:center}
.trade-action-row label{flex:1;min-width:0;font:700 9px var(--mono);color:#a7bbc4;display:flex;flex-direction:column;gap:5px}
.trade-input{width:100%;max-width:100%;padding:10px;background:#0b1a22;border:1px solid #49626b;border-radius:4px;color:white;font:700 14px var(--body)}
.trade-input:focus-visible{outline:2px solid #dabc83}
.trade-button{border:1px solid #ddb67c;border-radius:5px;padding:11px 12px;background:#e4ba77;color:#14222a;font:800 13px/1.1 var(--title);letter-spacing:.04em;min-height:41px}
.trade-button:hover{background:#f3d5a1}
.trade-button:disabled{opacity:.45;cursor:not-allowed}
.trade-button-secondary{background:#1a3340;color:#e6d5b4}
.trade-button-secondary:hover{background:#254b5a}
.trade-empty{padding:26px;background:#142935;border:1px dashed #4e6974;border-radius:8px;color:#c1d0d3;font-size:12px}
.trade-empty h2{font:800 28px var(--title);margin:0 0 9px}
.trade-status{font:700 9px var(--mono);color:#dbba7a;letter-spacing:.04em;padding:6px 0}
.trade-money{padding:20px;display:flex;flex-direction:column;gap:6px}
.trade-money span{font:700 10px var(--mono);color:#b9c8ce}
.trade-money strong{font:900 38px/1 var(--title);color:#f0c786}
.trade-money small{font-size:10px;color:#a6bbc2}
.trade-finance-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-bottom:17px}
.trade-ledger{padding:7px 17px 18px}
.trade-ledger-row{display:grid;grid-template-columns:66px minmax(0,1fr) auto;align-items:center;gap:12px;padding:12px 0;border-bottom:1px solid #304650;color:#d4e1e1;font-size:11px}
.trade-ledger-row time{color:#99acb5;font:700 10px var(--mono)}
.trade-ledger-row b{font:800 16px var(--title)}
.trade-positive{color:#9edab3}.trade-negative{color:#f1b7a1}
.trade-buyer-modes{display:grid;grid-template-columns:1fr 1fr;gap:10px;padding:12px 14px}
.trade-buyer-modes>div{background:#10232d;padding:12px;border:1px solid #3c5660;border-radius:5px;min-width:0}
.trade-buyer-modes h4{font:800 16px var(--title);letter-spacing:.03em;color:#eacb92}
.trade-buyer-modes p{font-size:11px;color:#bbcbce;line-height:1.4;margin:7px 0}
.trade-buyer-modes strong{font:800 21px var(--title);color:#fff0d0}
.trade-buyer-modes .trade-input{margin:8px 0}
.trade-buyer-modes .trade-button{width:100%}
.trade-card .trade-extra{display:block;font-size:10px;color:#92acb5;line-height:1.5;margin-top:6px}
.trade-stock-grid{padding:0}.trade-stock-grid .trade-card{min-height:300px}
.trade-sales-grid{padding:0}.trade-sales-grid .trade-card{grid-column:1/-1}
@media(max-width:900px){.trade-card-grid{grid-template-columns:1fr}.trade-finance-grid{grid-template-columns:1fr 1fr}.trade-buyer-modes{grid-template-columns:1fr 1fr}}
@media(max-width:540px){.trade-card-grid{padding:10px;gap:9px}.trade-stock-grid,.trade-sales-grid{padding:0}.trade-finance-grid{grid-template-columns:1fr}.trade-pricing strong{font-size:20px}.trade-buyer-modes{grid-template-columns:1fr}.trade-card-top{padding:12px}.trade-buyer-modes>div{padding:11px}.trade-ledger-row{grid-template-columns:51px minmax(0,1fr) auto;gap:6px;font-size:10px}}

/* Visible trading results, including when the user is scrolled down the catalogue. */
