.event-action-grid h3,.event-section h3{font:850 26px/1.1 var(--title);
 color:#f1d4a2;margin:0 0 10px}
.event-action-grid p,.event-section p{color:#b9cacc;font:500 12px/1.55 var(--body);margin:0 0 14px}
.event-section{padding:19px 22px;margin:0 0 15px}
.meeting-metrics{grid-template-columns:repeat(3,minmax(0,1fr))}
.meeting-notes>div{display:flex;gap:12px;border-bottom:1px solid #39505a;padding:12px 0}
.meeting-notes b{font:850 18px var(--title);color:#d7b47c}
.meeting-notes p{margin:0}
.meeting-staff-row,.meeting-minute{display:flex;justify-content:space-between;
 gap:10px;padding:11px 0;border-bottom:1px solid #3b525d;font:600 11px/1.5 var(--body);color:#bcd1d2}
.meeting-staff-row strong,.meeting-minute strong{color:#f2d49c}
.meeting-minute span{font:700 9px var(--mono);color:#a7c0c7}
.meeting-options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px}
.meeting-choice{display:flex;flex-direction:column;text-align:left;gap:11px;
 padding:17px 15px;background:#1e363e;border:1px solid #708078;border-radius:7px;
 color:#e1d4b9;cursor:pointer}
.meeting-choice strong{font:850 22px/1.1 var(--title);color:#efd5a7}
.meeting-choice span{font:500 11px/1.55 var(--body);color:#bcd1d2;flex:1}
.meeting-choice small{font:700 9px var(--mono);color:#e6bd7e}
.meeting-choice:hover:not(:disabled){background:#2a4547;border-color:#e9c080}
.meeting-choice:disabled{cursor:default;opacity:.65}
.deadline-retail-intro{padding:14px 17px;border:1px solid #a8885e;background:#342e27;
 border-radius:6px;margin:0 0 14px;grid-column:1/-1}
.deadline-retail-intro strong{color:#f1c383;font:800 19px var(--title)}
.deadline-retail-intro p{font:500 11px/1.5 var(--body);color:#d3c6b7;margin:6px 0 0}
.deadline-auction-closed{border:1px solid #986f50;background:#2c2b2a}
@media(max-width:1120px){.meeting-options{grid-template-columns:1fr}.deadline-hero{align-items:flex-start}}
@media(max-width:780px){.event-banner{flex-direction:column;align-items:stretch}
 .deadline-timeline{grid-template-columns:repeat(3,minmax(0,1fr))}
 .event-action-grid,.meeting-columns{grid-template-columns:1fr}
 .event-metrics,.meeting-metrics{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:570px){.deadline-hero{flex-direction:column;padding:18px}
 .deadline-alert{align-items:flex-start;text-align:left}
 .deadline-time{font-size:46px}.meeting-hero{padding:18px}
 .deadline-timeline{grid-template-columns:repeat(2,minmax(0,1fr))}
 .event-metrics>div,.meeting-metrics>div{padding:12px}
 .event-section{padding:15px}.event-action-grid>div{padding:15px}
 .event-banner h3{font-size:23px}}

/* Keep every department and the bottom career controls reachable at laptop height. */
@media(min-width:1021px){
  .career-sidebar{height:100dvh;min-height:0;overflow-y:auto;overscroll-behavior:contain;
    scrollbar-width:thin;scrollbar-color:#526570 #10202a}
  .sidebar-logo,.sidebar-bottom{flex-shrink:0}
}

/* Deal Day climate notice: distinct from a promised sale or reward. */
.deadline-climate{margin-top:11px!important;padding:10px 12px;border-left:3px solid #d8b478;
  background:rgba(7,20,27,.58);font:650 11px/1.5 var(--body);color:#e3d5bb}
.deadline-climate strong{font-weight:900;color:#f1c98e}

/* v0.8 workshop: practical two-column work board, not an arcade dashboard. */
.workshop-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 13px}
.workshop-summary>div{padding:17px 16px;background:linear-gradient(145deg,#203742,#122a35);
 border:1px solid #3c5862;border-radius:7px;min-width:0}
.workshop-summary small{display:block;color:#a7c0c9;font:700 9px/1.35 var(--mono);margin-bottom:9px}
.workshop-summary strong{display:block;color:#efd09b;font:900 32px/1 var(--title)}
.workshop-capacity{display:flex;flex-wrap:wrap;gap:9px;margin:0 0 14px}
.workshop-capacity span{padding:10px 12px;border:1px solid #4e6670;background:#132b35;
 color:#d3dfe0;border-radius:5px;font:700 10px/1.4 var(--mono)}
.workshop-list{display:grid;gap:16px;margin:14px 0}
.workshop-job{background:linear-gradient(145deg,#1b3440,#152c37);
 border:1px solid #536a72;border-radius:8px;overflow:hidden}
.workshop-job-heading{display:flex;justify-content:space-between;align-items:flex-start;gap:15px;
 padding:17px 19px;background:#203b45;border-bottom:1px solid #45616c}
.workshop-job-heading small{font:700 9px/1.4 var(--mono);color:#c5b08a}
.workshop-job-heading h3{font:900 clamp(25px,3vw,35px)/1 var(--title);margin:7px 0;color:#f6e5ca}
.workshop-job-heading span{display:inline-block;margin-top:3px;font:750 10px/1.4 var(--mono);color:#c8deca}
.workshop-finance{text-align:right;flex-shrink:0}
.workshop-finance small{display:block;color:#a9c3cb;font:700 9px var(--mono)}
.workshop-finance strong{display:block;font:850 23px var(--title);color:#f3d5a0;margin-top:5px}
.workshop-job-body{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1.25fr);gap:17px;padding:17px 19px}
.workshop-work{min-width:0}.workshop-work h4{font:850 21px var(--title);color:#e8c895;margin:0 0 12px}
.workshop-work>p{font:500 11px/1.6 var(--body);color:#abbfc4;margin:12px 0 0}
.workshop-item{display:flex;align-items:center;justify-content:space-between;gap:10px;
 padding:9px 0;border-bottom:1px solid #3d545c;font:550 11px/1.5 var(--body);color:#d1dfe1}
.workshop-item strong{font:850 17px var(--title);color:#e9d3aa;white-space:nowrap}
.workshop-fault span,.workshop-fault strong{color:#f1ac96}
.workshop-total span,.workshop-total strong{color:#f0c98d}
.workshop-job-controls{background:#102833;border:1px solid #344e59;padding:16px;border-radius:5px;min-width:0}
.workshop-action-panel p,.workshop-option p,.workshop-progress p,.workshop-finished p,
.workshop-stock-action p{font:500 11px/1.55 var(--body);color:#bdced1;margin:0 0 13px}
.workshop-options{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.workshop-option{min-width:0;border:1px solid #536873;border-radius:5px;
 padding:12px;background:#1c3741;display:flex;flex-direction:column;gap:10px}
.workshop-option h4{font:850 20px/1.1 var(--title);color:#efcd95;margin:0}
.workshop-option>strong{font:900 28px var(--title);color:#f5e2c0}
.workshop-option p{flex:1;margin:0}
.workshop-option .trade-button{font-size:12px}
.workshop-disabled{opacity:.7}
.workshop-progress{display:flex;justify-content:space-between;gap:12px;margin-bottom:16px}
.workshop-progress strong{font:850 22px var(--title);color:#f1d4a5}
.workshop-progress small{display:block;font:700 9px var(--mono);color:#adbdc2}
.workshop-finished strong{font:850 22px var(--title);color:#a1d5af}
.workshop-stock-action{display:flex;justify-content:space-between;gap:13px;align-items:center}
.workshop-stock-action p{margin:0}
@media(max-width:1150px){.workshop-job-body{grid-template-columns:1fr}.workshop-summary{grid-template-columns:repeat(2,1fr)}}
@media(max-width:660px){.workshop-options{grid-template-columns:1fr}.workshop-stock-action{flex-direction:column;align-items:stretch}
 .workshop-job-heading{padding:14px;flex-direction:column}.workshop-finance{text-align:left}
 .workshop-job-body{padding:12px}.workshop-job-controls{padding:12px}}

.workshop-disposal{border-top:1px solid #46616a;margin-top:17px;padding-top:15px}
.workshop-disposal strong{font:850 16px var(--title);color:#e5ae97}
.workshop-disposal p{font:500 11px/1.6 var(--body);color:#b9cbd0;margin:7px 0 12px}
.workshop-disposal .trade-button{border-color:#937868;background:#293039;color:#efc2ad}

/* v0.9 — customer enquiry, appointment and handover journey. */
.sales-pipeline-summary{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:11px;margin:0 0 14px}
.sales-pipeline-summary>div{padding:16px 17px;border:1px solid #47616b;
 background:linear-gradient(135deg,#1b3843,#142b36);border-radius:7px;min-width:0}
.sales-pipeline-summary small{display:block;color:#b3c6c9;
 font:700 9px/1.4 var(--mono);margin:0 0 7px}
.sales-pipeline-summary strong{display:block;color:#f0d2a2;
 font:900 clamp(20px,2.6vw,31px)/1 var(--title);overflow-wrap:anywhere}
.sales-pipeline-note{padding:13px 15px;margin:0 0 12px;
 border:1px solid #445b63;background:#142b35;border-radius:6px;
 font:500 11px/1.6 var(--body);color:#bacbd0}
.sales-pipeline-activity{border:1px solid #51646a;background:#213943;
 padding:10px 14px;margin-bottom:16px;border-radius:5px;
 color:#e3d0a8;font:750 10px/1.45 var(--mono)}
.sales-case-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,400px),1fr));
 gap:15px;margin:0 0 22px}
.sales-case-card{min-width:0}
.sales-case-card .trade-card-top small{color:#adbecc;font:700 9px/1.4 var(--mono)}
.sales-case-highlight{padding:16px 17px;background:#273b37;border:1px solid #789a79;
 border-radius:6px;display:flex;flex-direction:column;gap:10px}
.sales-case-highlight strong,.sales-case-highlight h4{color:#d9e5bf;
 font:850 20px/1.1 var(--title);margin:0}
.sales-case-highlight p{font:500 11px/1.55 var(--body);color:#d0ded4;margin:0}
.sales-case-quiet{padding:16px 17px;background:#2a302e;border:1px solid #586c70;
 border-radius:6px}
.sales-case-quiet strong{color:#c0c8c5;font:850 19px var(--title)}
.sales-case-quiet p{font:500 11px/1.6 var(--body);color:#bcc8c5;margin:10px 0 0}
.sales-customer-meta{display:flex;flex-wrap:wrap;gap:8px;padding:13px 14px;
 margin:10px 0 0;border:1px solid #405a63;background:#19323c;border-radius:5px}
.sales-customer-meta span{font:700 10px/1.4 var(--mono);color:#ecd1a1}
.sales-customer-meta span:first-child{color:#f2e3cc}
.sales-case-content{padding:15px 5px 8px}
.sales-case-content>p{font:500 12px/1.6 var(--body);color:#c0d0d2;margin:0 0 14px}
.sales-case-content .trade-button{margin:5px 3px 5px 0}
.sales-offer-modes{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0}
.sales-offer-mode{padding:14px;background:#172f39;border:1px solid #516873;
 border-radius:6px;min-width:0;display:flex;flex-direction:column;gap:8px}
.sales-offer-mode h4{font:850 20px/1 var(--title);color:#efd2a8;margin:0}
.sales-offer-mode small,.sales-offer-mode label{font:700 9px/1.4 var(--mono);color:#b5c7cf}
.sales-offer-mode>strong{font:850 29px/1.2 var(--title);color:#f2dfbe}
.sales-offer-mode p{font:500 11px/1.55 var(--body);color:#bacbd2;margin:0}
.sales-offer-mode>.trade-button{margin-top:auto}
@media(max-width:1150px){.sales-offer-modes{grid-template-columns:1fr}}
@media(max-width:780px){.sales-pipeline-summary{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:570px){.sales-case-grid{grid-template-columns:1fr}
 .sales-pipeline-summary>div{padding:11px}.sales-pipeline-activity{font-size:9px}
 .sales-customer-meta{padding:11px}.sales-case-content{padding:11px 0}}

/* Sales Office now contains a complete pipeline dashboard above its card grid. */
#sales-list.trade-sales-grid{display:block;min-width:0}
#sales-list .sales-case-grid{width:100%}

/* v0.9.1 PREMIUM REAL VEHICLE PHOTOGRAPHIC FLASHCARDS */
.trade-card,.sales-case-card,.workshop-job,.vehicle-sold-card{min-width:0}
.vehicle-photo-block{overflow:hidden;margin:0;border-radius:6px 6px 0 0;background:#111f2a}
.vehicle-photo-frame{position:relative;aspect-ratio:16/9;min-height:145px;max-height:285px;
 overflow:hidden;background:radial-gradient(circle at 50% 24%,#304955,#111f29 75%)}
.vehicle-photo-frame img{display:block;width:100%;height:100%;object-fit:cover;
 object-position:center 56%;filter:contrast(1.03);transition:transform .25s ease}
.trade-card:hover .vehicle-photo-frame img,.vehicle-sold-card:hover .vehicle-photo-frame img{transform:scale(1.025)}
.vehicle-photo-frame .vehicle-origin-tag,.vehicle-photo-frame .vehicle-grade-tag{position:absolute;top:11px;
 border:1px solid rgba(255,219,161,.45);background:rgba(10,24,31,.88);
 padding:6px 10px;color:#ffe0ad;border-radius:4px;font:800 10px/1.2 var(--mono);
 text-shadow:0 1px 2px #101820}
.vehicle-origin-tag{left:11px}.vehicle-grade-tag{right:11px}
/* Hidden image and fallback states must beat their display rules. */
.vehicle-photo-frame img[hidden],.vehicle-photo-missing[hidden]{display:none!important}
.vehicle-photo-missing{height:100%;display:flex;flex-direction:column;
 align-items:center;justify-content:center;text-align:center;gap:7px;padding:18px}
.vehicle-photo-missing>span{display:block;font:900 68px/1 var(--title);color:#536c78}
.vehicle-photo-missing strong{font:900 22px/1 var(--title);letter-spacing:.06em;color:#d2d9dd}
.vehicle-photo-missing small{font:600 11px/1.4 var(--body);color:#a8bec5}
.vehicle-photo-credit{display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap;
 padding:7px 11px;background:#142a34;border-bottom:1px solid #384b55;color:#92aeb8;
 font:600 9px/1.45 var(--body)}
.vehicle-photo-credit a{color:#f3c98c;text-decoration:underline;text-decoration-color:rgba(243,201,140,.3)}
.vehicle-photo-credit span{font-style:italic}
.vehicle-card-heading{padding:16px 16px 10px}
.vehicle-card-heading small{font:800 9px var(--mono);color:#c3a578}
.vehicle-card-heading h3{font:900 clamp(25px,2.7vw,33px)/1.05 var(--title);
 color:#f0e2cf;margin:6px 0;overflow-wrap:anywhere}
.vehicle-card-heading p{font:600 11px/1.4 var(--body);color:#c0cdd0;margin:8px 0 0}
.vehicle-card-statline{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));
 gap:7px;margin:0 15px 10px}
.vehicle-card-statline>div{background:#142c36;border:1px solid #38505b;border-radius:4px;
 padding:9px 9px;min-width:0}
.vehicle-card-statline small{display:block;font:800 8px/1.3 var(--mono);color:#9baeb8}
.vehicle-card-statline strong{display:block;margin-top:4px;font:800 12px/1.4 var(--body);color:#f3ddbd}
.vehicle-card-money{min-width:0;padding:12px;border:1px solid #45606a;background:#182f3a}
.vehicle-card-money small{display:block;color:#b8c7c9;font:700 10px var(--mono)}
.vehicle-card-money strong{font:900 24px var(--title);color:#f0ce92}
.vehicle-mini{display:grid;grid-template-columns:145px minmax(0,1fr);gap:12px;
 align-items:center;padding:10px;background:#1c3743;border:1px solid #526974;border-radius:5px;margin:8px 0}
.vehicle-mini .vehicle-photo-frame{aspect-ratio:16/10;min-height:90px;max-height:100px}
.vehicle-mini .vehicle-photo-credit{padding:5px;font-size:8px}
.vehicle-mini .vehicle-photo-credit span,.vehicle-mini .vehicle-grade-tag{display:none}
.vehicle-mini .vehicle-origin-tag{font-size:8px;padding:3px 5px;top:5px;left:5px}
.vehicle-mini .vehicle-photo-missing>span{font-size:28px}
.vehicle-mini .vehicle-photo-missing strong{font-size:12px}
.vehicle-mini .vehicle-photo-missing small{display:none}
.vehicle-mini-copy{display:flex;flex-direction:column;gap:7px;min-width:0}
.vehicle-mini-copy strong{font:850 20px var(--title);color:#edd4a9}
.vehicle-mini-copy span{font:600 11px/1.55 var(--body);color:#bad0d6}
.workshop-job>.vehicle-photo-block .vehicle-photo-frame{max-height:290px}
.sales-deposit-terms{font:600 10px/1.5 var(--body);color:#c5d5d0;margin:6px 0}
.sales-payment-breakdown{display:grid;grid-template-columns:minmax(0,1fr) auto;column-gap:12px;
 row-gap:8px;padding:10px;background:#102b33;border:1px solid #42645b;border-radius:5px}
.sales-payment-breakdown span{font:650 11px/1.4 var(--body);color:#b9cacc}
.sales-payment-breakdown strong{font:850 15px/1.25 var(--title);color:#edd5aa}
.sales-payment-breakdown span:nth-last-child(2),.sales-payment-breakdown strong:last-child{
 color:#f7d398;border-top:1px solid #55726a;padding-top:9px}
.sales-sold-recent{margin:22px 0 0}
.sales-sold-recent h3{font:850 27px var(--title);color:#edd2a9}
.sales-sold-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,350px),1fr));gap:12px}
.vehicle-sold-card{border:1px solid #45646d;background:#18323d;border-radius:7px;overflow:hidden}
.vehicle-sold-card .vehicle-photo-frame{max-height:205px}
.vehicle-sold-copy{padding:14px}
.vehicle-sold-copy h4{font:900 24px var(--title);color:#f1ddbb;margin:0 0 5px}
.vehicle-sold-copy>span{display:block;color:#b1c7ce;font:600 11px var(--body);margin:0 0 12px}
@media(max-width:580px){
 .vehicle-photo-frame{max-height:230px}.vehicle-mini{grid-template-columns:110px minmax(0,1fr)}
 .vehicle-card-statline{margin:0 10px 12px}.vehicle-card-heading{padding:12px}
 .vehicle-photo-credit span{display:block}
 .vehicle-card-statline strong{font-size:11px}
}

/* v0.9.3 — modern market progression and powertrain identification */
.market-progression{display:flex;align-items:center;justify-content:space-between;gap:18px;
 padding:16px 18px;margin:0 0 16px;border:1px solid #547080;border-radius:7px;
 background:linear-gradient(115deg,#193846,#0d2430)}
.market-progression>div{display:flex;flex-direction:column;gap:4px;flex-shrink:0}
.market-progression small{color:#a5bbc4;font:800 9px var(--mono);letter-spacing:.12em}
.market-progression strong{color:#f1cc8d;font:900 21px var(--title)}
.market-progression p{margin:0;max-width:550px;color:#c5d5db;font:600 11px/1.55 var(--body)}
.vehicle-powertrain-row{display:flex;gap:10px;align-items:center;flex-wrap:wrap;padding-top:8px;
 color:#b2c5cb;font:700 11px var(--body)}
.vehicle-powertrain{border:1px solid #56737b;border-radius:3px;padding:5px 8px;
 background:#24434d;color:#e0e9eb;font:900 10px/1 var(--mono);letter-spacing:.08em}
.vehicle-powertrain-electric{background:#163b43;border-color:#6db1b2;color:#b1f7e3}
.vehicle-powertrain-hybrid,.vehicle-powertrain-plug-in-hybrid{
 background:#263f32;border-color:#8bad83;color:#daf5b6}
.vehicle-powertrain-diesel{background:#3e3832;border-color:#86735e;color:#e6d0a8}
@media(max-width:650px){.market-progression{flex-direction:column;align-items:flex-start;gap:9px}}

/* v0.9.4 — provenance visible in the vehicle inspection dossier */
.vehicle-powertrain-mild-hybrid{background:#273f45;border-color:#639ba2;color:#d0edf0}
.vehicle-spec-proof{margin:14px 0;padding:13px 15px;border:1px solid #679c86;
 border-radius:5px;background:rgba(54,99,80,.13)}
.vehicle-spec-proof strong{display:block;color:#b2e5cc;font:800 11px/1.5 var(--mono);letter-spacing:.04em}
.vehicle-spec-proof p{margin:5px 0;color:var(--muted);font:500 12px/1.5 var(--body)}
.vehicle-spec-proof a{display:inline-block;margin-top:5px;color:#eac58a;
 font:800 10px/1.5 var(--mono);text-decoration:underline;text-underline-offset:3px}
.vehicle-spec-proof.vehicle-spec-pending{border-color:#675e4d;background:rgba(101,91,66,.10)}
.vehicle-spec-proof.vehicle-spec-pending strong{color:#e6c991}

/* v0.9.8 — premises investment, fixed overheads and facility capacity */
#premises-view{margin-top:18px}
.premises-section{padding-bottom:18px}
.premises-metrics{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:11px;padding:17px}
.premises-metrics>div{min-width:0;padding:15px 16px;border:1px solid #37515b;border-radius:8px;background:#192f39}
.premises-metrics small{display:block;font:700 9px/1.5 var(--mono);color:#aabec4}
.premises-metrics strong{display:block;font:900 28px/1.15 var(--title);color:#f2e6d2;margin-top:8px}
.premises-notice{margin:0 17px 14px}
.premises-upgrades{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;padding:0 17px 14px}
.premises-option{min-width:0;display:flex;flex-direction:column;align-items:flex-start;padding:19px;border:1px solid #44606a;background:linear-gradient(145deg,#203844,#162b34);border-radius:9px}
.premises-option h3{font:900 24px/1.1 var(--title);letter-spacing:.02em;color:#f1cf9d}
.premises-option>strong{font:800 22px/1.2 var(--title);margin:12px 0}
.premises-option p{font:500 11px/1.7 var(--body);color:#b8ccd0;margin-bottom:14px}
.premises-quote{width:100%;display:grid;grid-template-columns:minmax(0,1fr) auto;gap:10px 14px;margin:5px 0 16px;padding:14px 0;border-top:1px solid #47616b;border-bottom:1px solid #47616b}
.premises-quote span{font:700 9px/1.5 var(--mono);color:#b4c2c7}
.premises-quote b{font:800 12px/1.3 var(--mono);color:#f2debd;text-align:right}
.premises-option .trade-button{margin-top:auto}
.premises-option .trade-button:disabled{opacity:.65;cursor:not-allowed}
.premises-max{margin-top:auto;color:#add0b9;font:800 11px var(--mono)}
