#screen-menu .cloud-main-button:disabled {opacity:.5;cursor:wait}
#screen-menu #cloud-account-feedback {
  border-left:2px solid #d8b879;padding:7px 10px;
  background:#101e25;color:#f0d9b4;overflow-wrap:anywhere
}
#screen-menu #cloud-save-status {color:#e7c78e;overflow-wrap:anywhere}
#cloud-career-warning {border-left:3px solid #e1b66d}
@media(max-width:570px) {
  #screen-menu .menu-account-button {min-height:54px}
  #screen-menu .menu-account-button strong {font-size:18px}
  #screen-menu .cloud-account-panel {padding:13px}
  #screen-menu .cloud-actions {grid-template-columns:1fr}
  #screen-menu .cloud-actions button:first-child {grid-column:auto}
}
